package com.sih.analytics.entity; import com.sih.shared.tenant.TenantScopedEntity; import jakarta.persistence.*; import java.math.*; import java.time.*; import lombok.*; @Entity @Getter @Setter public class MetricSnapshot extends TenantScopedEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false)String category;@Column(nullable=false)String metricKey;@Column(nullable=false)String label;@Column(name="metric_value",nullable=false,precision=19,scale=4)BigDecimal value;String unit;@Column(nullable=false)OffsetDateTime measuredAt=OffsetDateTime.now();String sourceService;}